import { atom } from "jotai";
import { createSound } from "react-native-nitro-sound";

interface AudioTrack {
  url: string;
  trackId: string;
  duration: number;
}

interface AudioPlaybackState {
  currentTrack: AudioTrack | null;
  isPlaying: boolean;
  currentMs: number;
}

const eventId = atom<string | null>(null);

const soundInstanceAtom = atom(() => createSound());

const audioPlaybackAtom = atom<AudioPlaybackState>({
  currentTrack: null,
  isPlaying: false,
  currentMs: 0,
});

const loadTrackAtom = atom(null, (get, set, track: AudioTrack) => {
  const currentState = get(audioPlaybackAtom);

  // If loading a different track, reset state
  if (currentState.currentTrack?.trackId !== track.trackId) {
    set(audioPlaybackAtom, {
      currentTrack: track,
      isPlaying: false,
      currentMs: 0,
    });
  }
});

const setIsPlayingAtom = atom(null, (get, set, isPlaying: boolean) => {
  const currentState = get(audioPlaybackAtom);
  set(audioPlaybackAtom, {
    ...currentState,
    isPlaying,
  });
});

const setCurrentMsAtom = atom(null, (get, set, currentMs: number) => {
  const currentState = get(audioPlaybackAtom);
  set(audioPlaybackAtom, {
    ...currentState,
    currentMs,
  });
});

const resetPlaybackAtom = atom(null, (get, set) => {
  const currentState = get(audioPlaybackAtom);
  set(audioPlaybackAtom, {
    ...currentState,
    isPlaying: false,
    currentMs: 0,
  });
});

export const RecorderPlayerAtoms = {
  soundInstanceAtom,
  audioPlaybackAtom,
  loadTrackAtom,
  setIsPlayingAtom,
  setCurrentMsAtom,
  resetPlaybackAtom,
  eventId,
};

