import { useAtomValue, useSetAtom } from "jotai";
import type { FC, PropsWithChildren } from "react";
import { useEffect, useRef } from "react";
import { RecorderPlayerAtoms } from "../jotai";

export const AudioPlaybackProvider: FC<PropsWithChildren> = ({ children }) => {
  const isListenersSetup = useRef(false);
  const sound = useAtomValue(RecorderPlayerAtoms.soundInstanceAtom);
  const setCurrentMs = useSetAtom(RecorderPlayerAtoms.setCurrentMsAtom);
  const resetPlayback = useSetAtom(RecorderPlayerAtoms.resetPlaybackAtom);

  useEffect(() => {
    if (isListenersSetup.current) return;
    isListenersSetup.current = true;

    sound.addPlayBackListener((e) => {
      setCurrentMs(e.currentPosition);
    });

    sound.addPlaybackEndListener(() => {
      resetPlayback();
    });

    // Cleanup on unmount
    return () => {
      sound.removePlayBackListener();
      sound.removePlaybackEndListener();
      isListenersSetup.current = false;
    };
  }, [sound, setCurrentMs, resetPlayback]);

  return <>{children}</>;
};

