import { AudioContext } from "react-native-audio-api";
import type { AudioBuffer, AudioBufferSourceNode } from "react-native-audio-api";

class OggPlayerServiceClass {
  private audioContext: AudioContext | null = null;
  private sourceNode: AudioBufferSourceNode | null = null;
  private audioBuffer: AudioBuffer | null = null;
  private _isPlaying = false;
  private _currentMs = 0;
  private onProgressCallback: ((ms: number) => void) | null = null;
  private onEndCallback: (() => void) | null = null;

  private getContext(): AudioContext {
    if (!this.audioContext || this.audioContext.state === "closed") {
      this.audioContext = new AudioContext();
    }
    return this.audioContext;
  }

  private startSource(offsetSeconds: number) {
    const ctx = this.getContext();

    this.sourceNode = ctx.createBufferSource();
    this.sourceNode.buffer = this.audioBuffer!;
    this.sourceNode.connect(ctx.destination);

    this.sourceNode.onPositionChangedInterval = 100;
    this.sourceNode.onPositionChanged = (event) => {
      this._currentMs = event.value * 1000;
      this.onProgressCallback?.(this._currentMs);
    };

    this.sourceNode.onEnded = () => {
      this._isPlaying = false;
      this._currentMs = 0;
      this.onEndCallback?.();
    };

    this.sourceNode.start(ctx.currentTime, offsetSeconds);
    this._isPlaying = true;
  }

  async play(
    url: string,
    onProgress: (ms: number) => void,
    onEnd: () => void,
  ) {
    this.stop();

    const ctx = this.getContext();
    if (ctx.state === "suspended") {
      await ctx.resume();
    }

    this.audioBuffer = await ctx.decodeAudioData(url);
    this.onProgressCallback = onProgress;
    this.onEndCallback = onEnd;

    this.startSource(0);
  }

  async pause() {
    if (!this._isPlaying || !this.sourceNode) return;

    try {
      this.sourceNode.onEnded = null;
      this.sourceNode.stop(0);
    } catch (e) {
      // ignore
    }
    this.sourceNode = null;

    const ctx = this.getContext();
    await ctx.suspend();

    this._isPlaying = false;
  }

  async resume() {
    if (this._isPlaying || !this.audioBuffer) return;

    const ctx = this.getContext();
    await ctx.resume();

    const offsetSeconds = this._currentMs / 1000;
    this.startSource(offsetSeconds);
  }

  stop() {
    try {
      if (this.sourceNode) {
        this.sourceNode.onPositionChanged = null;
        this.sourceNode.onEnded = null;
        this.sourceNode.stop(0);
        this.sourceNode = null;
      }
    } catch (e) {
      // ignore
    }
    this._isPlaying = false;
    this._currentMs = 0;
    this.onProgressCallback = null;
    this.onEndCallback = null;
  }
}

export const OggPlayerService = new OggPlayerServiceClass();

